// #4101 — the wake decision. The verdict matters more than the happy path: a false reported as success
// leaves a dead worker (#4025). And the KILL matters as much as the verdict: without it a pane whose
// shell outlived its agent reconnects instead of spawning, so the wake lands nowhere while reporting
// success (#wake-restarts-a-pane-whose-shell-outlived-claude).
import { describe, it, expect, vi } from "vitest";
import { applyWake, DEFAULT_WAKE_PROMPT, wakePrecheckCwd } from "@/app/fleetWakeBridge";

/** Deps with a recording kill, defaulting to a wake that lands. */
function deps(over: { wakePane?: (p: string, t: string) => boolean; killPane?: (p: string) => Promise<void> } = {}) {
  const calls: string[] = [];
  const killPane = over.killPane ?? (async (p: string) => { calls.push(`kill:${p}`); });
  const inner = over.wakePane ?? (() => true);
  const wakePane = vi.fn((p: string, t: string) => { calls.push(`wake:${p}`); return inner(p, t); });
  return { d: { wakePane, killPane }, wakePane, calls };
}

describe("applyWake", () => {
  it("wakes the pane and reports the verdict", async () => {
    const { d, wakePane } = deps();
    expect(await applyWake("r1", { paneId: "proj:api", prompt: "rebase onto develop" }, d)).toEqual({
      id: "r1",
      woke: true,
    });
    expect(wakePane).toHaveBeenCalledWith("proj:api", "rebase onto develop", undefined);
  });

  it("supplies the standard wake prompt when the caller gives none", async () => {
    const { d, wakePane } = deps();
    await applyWake("r2", { paneId: "proj:api" }, d);
    expect(wakePane).toHaveBeenCalledWith("proj:api", DEFAULT_WAKE_PROMPT, undefined);
    // A whitespace-only prompt is the same as none — otherwise the worker wakes to a blank task.
    await applyWake("r3", { paneId: "proj:api", prompt: "   " }, d);
    expect(wakePane).toHaveBeenLastCalledWith("proj:api", DEFAULT_WAKE_PROMPT, undefined);
  });

  it("carries a FALSE verdict through instead of reporting success", async () => {
    // The #4025 shape: wakePane cannot resolve the pane, so nothing was woken — but the kill already
    // happened. Reporting `woke: true` here is what made that bug silent.
    const { d } = deps({ wakePane: () => false });
    expect((await applyWake("r4", { paneId: "ghost" }, d)).woke).toBe(false);
  });

  it("rejects an empty pane id without touching the store", async () => {
    const { d, wakePane, calls } = deps();
    const ack = await applyWake("r5", { paneId: "  " }, d);
    expect(ack.woke).toBe(false);
    expect(ack.error).toMatch(/no pane id/);
    expect(wakePane).not.toHaveBeenCalled();
    expect(calls).toEqual([]); // and nothing was killed either
  });

  // ── The regression this item exists for ──────────────────────────────────────────────────────────
  //
  // A pane whose SHELL is alive but whose agent has exited (`live && !busy` in `bsc fleet list`) used
  // to reconnect: `wakePane` only bumps `runId`, and `pty_create` reconnects rather than spawning when
  // a PTY already exists, discarding the baked prompt. Claude never started and `woke: true` was
  // returned anyway.
  it("KILLS the PTY before waking, so the remount spawns instead of reconnecting", async () => {
    const { d, calls } = deps();
    await applyWake("r6", { paneId: "proj:api" }, d);
    expect(calls).toEqual(["kill:proj:api", "wake:proj:api"]);
  });

  it("still wakes when there is nothing to kill (a dormant/reaped pane)", async () => {
    // `pty_kill` on an absent session rejects. Aborting there would break the case the command was
    // built for — a reaped worker is precisely the one with no PTY.
    const { d, wakePane } = deps({ killPane: () => Promise.reject(new Error("no such session")) });
    const ack = await applyWake("r7", { paneId: "proj:reaped" }, d);
    expect(ack.woke).toBe(true);
    expect(wakePane).toHaveBeenCalledWith("proj:reaped", DEFAULT_WAKE_PROMPT, undefined);
  });

  it("does not report success when the kill succeeded but the wake found no tab", async () => {
    // Both halves must hold: killing is not evidence of waking.
    const { d } = deps({ wakePane: () => false });
    expect((await applyWake("r8", { paneId: "proj:orphan" }, d)).woke).toBe(false);
  });
  // ── STARTING a stream that never launched (#the-director-cannot-start-a-stream-that-never-launched) ──
  //
  // The store cannot read plan.db, so a stream it has never seen is startable ONLY because Rust resolved
  // the row and sent it. This bridge is the conduit, and a conduit that drops its payload fails silently:
  // `wakePane` would refuse exactly as before and the director would be told the pane resolved to no tab.
  it("hands the plan row straight through to wakePane", async () => {
    const { d, wakePane } = deps();
    const stream = { id: "api", name: "API", repo: "own/api", owns: [], issues: [], dependsOn: [], cwd: "/wt/api" };
    await applyWake("r9", { paneId: "proj:api", prompt: "start on #7", stream }, d);
    expect(wakePane).toHaveBeenCalledWith("proj:api", "start on #7", stream);
  });

  it("passes NOTHING when Rust resolved nothing — the refusal must stay reachable", async () => {
    // Absence is meaningful in both directions: a live pane never needed a lookup, and a not-live pane
    // whose stream plan.db does not name gets none. Forwarding a placeholder would turn an unknown
    // stream into a started one.
    const { d, wakePane } = deps();
    await applyWake("r10", { paneId: "proj:ghost" }, d);
    expect(wakePane).toHaveBeenCalledWith("proj:ghost", DEFAULT_WAKE_PROMPT, undefined);
  });
});

describe("a refusal names its condition", () => {
  // The generic sentence — "it resolved to no open tab, or is disabled" — is already recorded in
  // `fleet/wake.rs` as having "sent three rounds of debugging at the frontend for a repo that was
  // simply not cloned". It did it again: a pane left DISABLED by an End session read as a missing
  // tab, twice. Rust returns `ack.error` verbatim when present, so naming the condition is the fix.
  const base = { killPane: async () => {}, wakePane: () => false };

  it("passes the frontend's reason through when the wake is refused", async () => {
    const ack = await applyWake("w1", { paneId: "proj:worker" } as never, {
      ...base,
      refusalReason: (p: string) => `'${p}' is DISABLED — re-enable it in the Console`,
    } as never);
    expect(ack.woke).toBe(false);
    expect(ack.error).toContain("DISABLED");
    expect(ack.error).toContain("proj:worker");
  });

  it("says nothing specific when there is nothing specific to say", async () => {
    const ack = await applyWake("w2", { paneId: "proj:worker" } as never, { ...base } as never);
    expect(ack.woke).toBe(false);
    expect(ack.error).toBeUndefined();   // Rust falls back to its own sentence
  });

  it("carries no reason when the wake LANDS — a reason would read as a failure", async () => {
    const ack = await applyWake("w3", { paneId: "proj:worker" } as never, {
      killPane: async () => {},
      wakePane: () => true,
      refusalReason: () => "must not be used",
    } as never);
    expect(ack.woke).toBe(true);
    expect(ack.error).toBeUndefined();
  });
});

describe("wakePrecheckCwd", () => {
  // Requests #142/#150 -- this selection IS the whole bug. Asking pty_launch_refusal about the
  // STORE's cwd for a stream wakePane has not adopted yet can only ever answer "refused", because
  // the store is empty until wakePane itself sets it from req.stream.cwd -- and by then the precheck
  // has already run and refused. req.stream.cwd must win whenever Rust resolved one.
  it("prefers the freshly-resolved stream cwd over the stale store cwd", () => {
    const stream = { id: "api", name: "API", repo: "own/api", owns: [], issues: [], dependsOn: [], cwd: "/wt/api" };
    expect(wakePrecheckCwd({ paneId: "proj:api", stream }, "")).toBe("/wt/api");
    // Even when the store DOES hold something -- a worktree that had to be rebuilt -- Rust's fresh
    // resolve still wins, since it is the one that reflects what the imminent launch will actually use.
    expect(wakePrecheckCwd({ paneId: "proj:api", stream }, "/wt/api-stale")).toBe("/wt/api");
  });

  it("falls back to the store cwd for an ordinary live-pane wake (no resolved stream)", () => {
    expect(wakePrecheckCwd({ paneId: "proj:api" }, "/wt/api")).toBe("/wt/api");
  });

  it("is empty, never undefined, when neither source has one", () => {
    expect(wakePrecheckCwd({ paneId: "proj:ghost" }, "")).toBe("");
  });
});

// A wake must not destroy a session it cannot bring back —
// `a-wake-kills-a-pane-it-cannot-relaunch-and-reports-success`.
//
// WHY THIS FILE IS SEPARATE FROM THE RECORD'S CARRIED TEST. `fleetWakeBridge` is a record, and a
// record's carried test can only be written by `bsc graph tests harvest`, which pairs by COLOCATED
// FILE — and this module's file was retired, so its test is frozen at whatever it was when the file
// last existed (filed as `bsc request` 138). If that gap closes, fold these back onto the record.
//
// THE BUG, measured on the live network-monitor fleet. The director woke sessions with a prompt and
// they all shut down. Three links:
//
//   1. `applyWake` kills the PTY FIRST, unconditionally — deliberately, because without it the
//      remount reconnects to a live shell and the baked prompt is silently discarded.
//   2. `wakePane`'s verdict answers ONE question: could an owning tab and a grid seat be resolved.
//      It never asks whether the relaunch can succeed.
//   3. `pty_create` then REFUSES a project-identity pane whose cwd has no `.claude/settings.json`
//      (`must_be_gated` + the #1819 guard). That refusal is correct — an ungated director or worker
//      is worse than none — but it lands AFTER the frontend has acked `woke: true`.
//
// Four worktrees were in that state (host-operations-adapter, nac-and-freeradius-adapter,
// omada-controller-adapter, opnsense-config-adapter): complete except for `.claude/`. Waking any of
// them destroyed a live session, got refused, and reported success. The command's own help already
// warned about the shape — "the wake path kills first, so a false success would leave a dead worker
// behind a caller that believes it is running" — there was simply no way to ask in advance.
import { describe, it, expect, vi } from "vitest";
import { applyWake } from "@/app/fleetWakeBridge";

/** Deps with a recording kill, defaulting to a wake that lands — mirrors the record's own helper. */
function deps(over: { wakePane?: () => boolean } = {}) {
  const calls: string[] = [];
  const killPane = async (p: string) => { calls.push(`kill:${p}`); };
  const inner = over.wakePane ?? (() => true);
  const wakePane = vi.fn((p: string) => { calls.push(`wake:${p}`); return inner(); });
  return { d: { wakePane, killPane }, wakePane, calls };
}

const REFUSAL =
  "pty[proj:api] refusing to auto-launch claude at /wt/api — no .claude/settings.json, so the role " +
  "gate and shell allowlist were never written and the session would run permission-less (#1819).";

describe("a wake does not destroy a session it cannot bring back", () => {
  it("REFUSES without killing when the launch would be refused", async () => {
    const { d, wakePane, calls } = deps();
    const ack = await applyWake("g1", { paneId: "proj:api" }, {
      ...d,
      launchRefusal: async () => REFUSAL,
    } as never);

    expect(ack.woke).toBe(false);
    // The launch's OWN words, not a generic sentence. `fleet/wake.rs` records that the generic
    // refusal "sent three rounds of debugging at the frontend for a repo that was simply not cloned".
    expect(ack.error).toBe(REFUSAL);
    expect(calls).toEqual([]);                // NOTHING was killed — the whole point
    expect(wakePane).not.toHaveBeenCalled();  // ...and nothing was woken either
  });

  it("proceeds normally, in order, when the launch would be admitted", async () => {
    const { d, calls } = deps();
    const ack = await applyWake("g2", { paneId: "proj:api" }, {
      ...d,
      launchRefusal: async () => undefined,
    } as never);
    expect(ack.woke).toBe(true);
    // Kill still precedes wake — the pre-check must not have reordered the load-bearing part.
    expect(calls).toEqual(["kill:proj:api", "wake:proj:api"]);
  });

  it("does not refuse the wake when the pre-check itself fails", async () => {
    // A guard, not a gate on the app being healthy. If asking throws — command missing, backend
    // mid-restart — fall back to the previous behaviour: this fixes killing a pane we KNOW cannot
    // relaunch, not refusing whenever we are unsure. Failing closed here would make a backend hiccup
    // look exactly like a broken worktree.
    const { d, calls } = deps();
    const ack = await applyWake("g3", { paneId: "proj:api" }, {
      ...d,
      launchRefusal: () => Promise.reject(new Error("no such command")),
    } as never);
    expect(ack.woke).toBe(true);
    expect(calls).toEqual(["kill:proj:api", "wake:proj:api"]);
  });

  it("behaves exactly as before when no pre-check is wired at all", async () => {
    // The dep is optional so an older caller — or a test that does not care — is unchanged.
    const { d, calls } = deps();
    expect((await applyWake("g4", { paneId: "proj:api" }, d as never)).woke).toBe(true);
    expect(calls).toEqual(["kill:proj:api", "wake:proj:api"]);
  });

  it("still reports a store-side refusal, which is a different condition", async () => {
    // The pre-check covers "the launch will refuse". `wakePane` returning false covers "no open tab,
    // or disabled". Both must stay reachable and distinguishable — collapsing them is what produced
    // the one-sentence refusal that listed every possible cause.
    const { d } = deps({ wakePane: () => false });
    const ack = await applyWake("g5", { paneId: "proj:orphan" }, {
      ...d,
      launchRefusal: async () => undefined,
      refusalReason: () => "'proj:orphan' is DISABLED — re-enable it in the Console",
    } as never);
    expect(ack.woke).toBe(false);
    expect(ack.error).toContain("DISABLED");
  });
});
